WITH metrics AS (SELECT *, LAST_VALUE(browser, TRUE) OVER (PARTITION BY country, customer_id ORDER BY started_at, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) last_known_browser, ROW_NUMBER() OVER (PARTITION BY device, customer_id ORDER BY started_at, id) event_seq FROM sessions), deduped AS (SELECT * FROM metrics QUALIFY RANK() OVER (PARTITION BY device ORDER BY event_seq NULLS FIRST) = 1), scored AS (SELECT *, SUM(event_seq) OVER w_recent running_sum_event_seq, MAX(event_seq) OVER w_recent running_max_event_seq, COUNT(event_seq) OVER w_recent running_count_event_seq, MIN(event_seq) OVER w_recent running_min_event_seq, AVG(event_seq) OVER (ORDER BY started_at, id ROWS BETWEEN 6 PRECEDING AND 1 PRECEDING) event_seq_avg_6_prior FROM deduped WHERE device = 'tablet' WINDOW w_recent AS (PARTITION BY country, device ORDER BY event_seq, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW)), with_dims AS (SELECT a.*, b.segment, b.email, b.name FROM scored a INNER JOIN customers b ON a.customer_id <=> b.id), with_latest AS (SELECT s.id, s.browser, s.event_seq, s.running_sum_event_seq, s.running_count_event_seq, latest.page, latest.web_event_event_time FROM with_dims s LEFT JOIN LATERAL (SELECT c.page, c.event_time AS web_event_event_time FROM web_events c WHERE c.session_id = s.id ORDER BY c.duration_sec DESC, c.id DESC LIMIT 1) latest ON TRUE), with_gaps AS (SELECT *, CASE WHEN LAG(web_event_event_time) OVER (PARTITION BY page ORDER BY web_event_event_time, id) IS NULL OR web_event_event_time > LAG(web_event_event_time) OVER (PARTITION BY page ORDER BY web_event_event_time, id) + INTERVAL '7' DAY THEN 1 ELSE 0 END AS is_new_burst FROM with_latest), sessions_sessions AS (SELECT *, SUM(is_new_burst) OVER (PARTITION BY page ORDER BY web_event_event_time, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS session_id FROM with_gaps), latest AS (SELECT id, running_sum_event_seq, running_count_event_seq, page, is_new_burst FROM sessions_sessions QUALIFY ROW_NUMBER() OVER (PARTITION BY browser, page ORDER BY running_sum_event_seq DESC, id) = 1) SELECT page, AVG(running_count_event_seq) FILTER (WHERE page = '/checkout') AS checkout_avg_running_count_event_seq, COUNT(*) AS cnt, COUNT(DISTINCT id) AS distinct_ids, ROUND(AVG(running_sum_event_seq), 2) AS avg_running_sum_event_seq FROM latest GROUP BY page;
